char *path = "/usr/bin/ls";
char *const argv[] = {"ls", "-l", NULL};
char *const envp[] = {NULL};

// Process replacement attempt
// If successful, the new program (ls) takes over,
// and execution never returns past this line.
execve(path, argv, envp);

// The calling process continues ONLY if execve() fails
// (e.g., file not found, permission denied).
perror("execve");
return 1; // Indicate failure in original process context
// Current process image is NOT replaced on error.
